import React from "react";

// BrandLoader — the single loader for the whole app.
//
// Traces the actual Unideals logo artwork (paths from public/logo.svg)
// with a premium draw-on loop (dashoffset 1000 -> 0 -> hold -> back,
// 2.2s indefinite) in the brand indigo gradient, over a faint filled
